#include <Arduino.h>

// =======================================
// Bipolar Stepper Motor - Arduino + L298
// Embedded Systems HW1 - Question 3
// =======================================

// ---------- Motor specifications ----------
const float STEP_ANGLE_DEG = 1.8f;
const uint16_t STEPS_PER_REV =
    (uint16_t)(360.0f / STEP_ANGLE_DEG + 0.5f);

// ---------- Arduino pins ----------
const uint8_t MOTOR_PINS[4] = {8, 9, 10, 11};
const uint8_t POT_PIN = A0;
const uint8_t BUTTON_PIN = 2;
const uint8_t DEBUG_PIN = 13;

// ---------- Full-step sequence ----------
const uint8_t SEQ_LEN = 4;
const uint8_t NUM_PINS = 4;

const uint8_t STEP_SEQ[SEQ_LEN][NUM_PINS] = {
  {HIGH, LOW,  HIGH, LOW },
  {LOW,  HIGH, HIGH, LOW },
  {LOW,  HIGH, LOW,  HIGH},
  {HIGH, LOW,  LOW,  HIGH}
};

// ---------- Timing ----------
const uint16_t MIN_DELAY_MS = 2;
const uint16_t MAX_DELAY_MS = 20;
const uint16_t FIXED_DELAY_MS = 20;

const unsigned long PAUSE_MS = 1000;
const unsigned long DEBOUNCE_MS = 50;

// ---------- Speed smoothing ----------
const uint16_t RAMP_STEPS = 40;
const bool ENABLE_RAMP = true;

// Set true only for constant-speed debugging
const bool TEST_FIXED_SPEED = false;

// Change to -1 if physical CW/CCW is reversed
const int8_t CW_SIGN = 1;

// ---------- Motor states ----------
enum MotionState {
  RUN_CW,
  PAUSE_AFTER_CW,
  RUN_CCW
};

MotionState state = RUN_CW;

uint8_t stepIndex = 0;
uint16_t stepsDone = 0;

bool manualReverse = false;

unsigned long lastStepMs = 0;
unsigned long pauseStartMs = 0;

// ---------- Button debounce ----------
bool lastReading = HIGH;
bool stableButton = HIGH;
unsigned long lastDebounceMs = 0;

// ---------- Potentiometer ----------
int filteredPot = 0;

// =======================================
// Apply one phase from the sequence
// =======================================
void applyStep(uint8_t index) {
  for (uint8_t i = 0; i < NUM_PINS; i++) {
    digitalWrite(MOTOR_PINS[i],
                 STEP_SEQ[index][i]);
  }
}

// =======================================
// Read speed from potentiometer
// =======================================
uint16_t getTargetDelay() {

  if (TEST_FIXED_SPEED) {
    return FIXED_DELAY_MS;
  }

  int raw = analogRead(POT_PIN);

  // Low-pass filter to reduce speed jitter
  filteredPot = (filteredPot * 7 + raw) / 8;

  return (uint16_t)map(
    filteredPot,
    0, 1023,
    MAX_DELAY_MS, MIN_DELAY_MS
  );
}

// =======================================
// Acceleration and deceleration
// =======================================
uint16_t getStepDelay() {

  uint16_t target = getTargetDelay();

  if (!ENABLE_RAMP || TEST_FIXED_SPEED) {
    return target;
  }

  uint16_t remaining =
      STEPS_PER_REV - 1 - stepsDone;

  uint16_t distanceFromEdge =
      min(stepsDone, remaining);

  if (distanceFromEdge >= RAMP_STEPS) {
    return target;
  }

  return MAX_DELAY_MS -
    ((MAX_DELAY_MS - target) *
     distanceFromEdge / RAMP_STEPS);
}

// =======================================
// Detect one valid button press
// =======================================
void checkButton(unsigned long now) {

  bool reading = digitalRead(BUTTON_PIN);

  if (reading != lastReading) {
    lastDebounceMs = now;
  }

  lastReading = reading;

  if (now - lastDebounceMs >= DEBOUNCE_MS) {

    if (reading != stableButton) {

      stableButton = reading;

      // Active-low: reverse on pressing,
      // not on releasing
      if (stableButton == LOW) {

        manualReverse = !manualReverse;

        // Start a fresh 360-degree command
        // in the newly selected direction
        if (state != PAUSE_AFTER_CW) {
          stepsDone = 0;
          lastStepMs = now - MAX_DELAY_MS;
        }
      }
    }
  }
}

// =======================================
// Determine actual command direction
// =======================================
int8_t getDirection() {

  int8_t direction =
      (state == RUN_CCW) ? -1 : 1;

  if (manualReverse) {
    direction = -direction;
  }

  return direction * CW_SIGN;
}

// =======================================
// Execute one full step
// =======================================
void executeStep(int8_t direction) {

  if (direction > 0) {
    stepIndex = (stepIndex + 1) % SEQ_LEN;
  } else {
    stepIndex =
        (stepIndex + SEQ_LEN - 1) % SEQ_LEN;
  }

  applyStep(stepIndex);

  // Direction monitor on D13
  digitalWrite(DEBUG_PIN,
               direction < 0 ? HIGH : LOW);
}

// =======================================
// Setup
// =======================================
void setup() {

  for (uint8_t i = 0; i < NUM_PINS; i++) {
    pinMode(MOTOR_PINS[i], OUTPUT);
    digitalWrite(MOTOR_PINS[i], LOW);
  }

  pinMode(POT_PIN, INPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  pinMode(DEBUG_PIN, OUTPUT);
  digitalWrite(DEBUG_PIN, LOW);

  lastReading = digitalRead(BUTTON_PIN);
  stableButton = lastReading;
  lastDebounceMs = millis();

  filteredPot = analogRead(POT_PIN);

  stepIndex = 0;
  stepsDone = 0;
  manualReverse = false;
  state = RUN_CW;

  applyStep(stepIndex);

  lastStepMs = millis() - MAX_DELAY_MS;
}

// =======================================
// Main loop
// =======================================
void loop() {

  unsigned long now = millis();

  // Continuously check button
  checkButton(now);

  // -------- One-second pause --------
  if (state == PAUSE_AFTER_CW) {

    if (now - pauseStartMs >= PAUSE_MS) {

      state = RUN_CCW;
      stepsDone = 0;
      lastStepMs = now - MAX_DELAY_MS;
    }

    return;
  }

  // -------- Motor speed --------
  uint16_t interval = getStepDelay();

  if (now - lastStepMs < interval) {
    return;
  }

  lastStepMs = now;

  // -------- Motor step --------
  int8_t direction = getDirection();

  executeStep(direction);
  stepsDone++;

  // -------- One complete revolution --------
  if (stepsDone >= STEPS_PER_REV) {

    stepsDone = 0;

    if (state == RUN_CW) {

      // CW -> wait 1 second -> CCW
      state = PAUSE_AFTER_CW;
      pauseStartMs = now;

    } else {

      // CCW -> CW automatically
      state = RUN_CW;
    }
  }
}
